CREATE OR REPLACE VIEW ACOCO_L1.ORGANISATION.COST_CENTER
  COMMENT = 'L1 ORGANISATION.COST_CENTER: one row per business object; sources BDC_CLD. Generated from tools/l1_map.yml - do not edit.'
AS
  SELECT
    CAST(c."ControllingArea" AS VARCHAR) AS CONTROLLING_AREA,
    CAST(UPPER(TRIM(c."CostCenter")) AS VARCHAR) AS COST_CENTER_ID,
    CAST(c."CompanyCode" AS VARCHAR) AS COMPANY_CODE,
    CAST(UPPER(TRIM(c."ProfitCenter")) AS VARCHAR) AS PROFIT_CENTER_ID,
    CAST(c."CostCenterCategory" AS VARCHAR) AS COST_CENTER_CATEGORY,
    CAST(t."CostCenterName" AS VARCHAR) AS COST_CENTER_NAME,
    CAST(m.CC_ROLE AS VARCHAR) AS CC_ROLE,
    CAST(m.MD_GROUP_ID AS VARCHAR) AS MD_GROUP_ID,
    CAST(m.ACOCO_LABEL AS VARCHAR) AS ACOCO_LABEL,
    CAST(TRY_TO_DATE(c."ValidityStartDate"::VARCHAR) AS DATE) AS VALID_FROM,
    CAST(TRY_TO_DATE(c."ValidityEndDate"::VARCHAR) AS DATE) AS VALID_TO,
    'BDC_CLD' AS SOURCE_SYSTEM
  FROM COSTCENTER_V1."costcenter"."costcenter" c
  LEFT JOIN COSTCENTER_V1."costcenter"."costcentertext" t
    ON t."ControllingArea" = c."ControllingArea" AND t."CostCenter" = c."CostCenter"
   AND t."Language" = 'EN' AND t."ValidityEndDate" = c."ValidityEndDate"
  LEFT JOIN ACOCO_DB.OPS.MAP_MD_GROUP m ON m.COST_CENTER = c."CostCenter"
  WHERE c."CompanyCode" = 'USC1';

CREATE OR REPLACE VIEW ACOCO_L1.ORGANISATION.COST_CENTER_HIERARCHY
  COMMENT = 'L1 ORGANISATION.COST_CENTER_HIERARCHY: one row per business object; sources BDC_CLD. Generated from tools/l1_map.yml - do not edit.'
AS
  SELECT
    CAST(n."CostCenterHierarchy" AS VARCHAR) AS HIERARCHY_ID,
    CAST(n."HierarchyNode" AS VARCHAR) AS NODE_ID,
    CAST(n."ParentNode" AS VARCHAR) AS PARENT_NODE_ID,
    CAST(TRY_TO_NUMBER(n."HierarchyNodeLevel"::VARCHAR) AS NUMBER) AS NODE_LEVEL,
    CAST(n."NodeType" AS VARCHAR) AS NODE_TYPE,
    CAST(NULLIF(UPPER(TRIM(n."CostCenter")), '') AS VARCHAR) AS COST_CENTER_ID,
    CAST(t."HierarchyNodeText" AS VARCHAR) AS NODE_TEXT,
    CAST(TRY_TO_DATE(n."ValidityStartDate"::VARCHAR) AS DATE) AS VALID_FROM,
    CAST(TRY_TO_DATE(n."ValidityEndDate"::VARCHAR) AS DATE) AS VALID_TO,
    'BDC_CLD' AS SOURCE_SYSTEM
  FROM COSTCENTER_V1."costcenter"."costcenterhierarchynode" n
  LEFT JOIN COSTCENTER_V1."costcenter"."costcenterhierarchynodetext" t
    ON t."CostCenterHierarchy" = n."CostCenterHierarchy" AND t."HierarchyNode" = n."HierarchyNode"
   AND t."ValidityEndDate" = n."ValidityEndDate" AND t."Language" = 'EN'
  WHERE n."CostCenterHierarchy" = '0101/A000/0001';

CREATE OR REPLACE VIEW ACOCO_L1.ORGANISATION.PROFIT_CENTER
  COMMENT = 'L1 ORGANISATION.PROFIT_CENTER: one row per business object; sources BDC_CLD. Generated from tools/l1_map.yml - do not edit.'
AS
  SELECT
    CAST(p."ControllingArea" AS VARCHAR) AS CONTROLLING_AREA,
    CAST(UPPER(TRIM(p."ProfitCenter")) AS VARCHAR) AS PROFIT_CENTER_ID,
    CAST(p."CompanyCode" AS VARCHAR) AS COMPANY_CODE,
    CAST(t."ProfitCenterName" AS VARCHAR) AS PROFIT_CENTER_NAME,
    CAST(p."Segment" AS VARCHAR) AS SEGMENT,
    CAST(TRY_TO_DATE(p."ValidityStartDate"::VARCHAR) AS DATE) AS VALID_FROM,
    CAST(TRY_TO_DATE(p."ValidityEndDate"::VARCHAR) AS DATE) AS VALID_TO,
    'BDC_CLD' AS SOURCE_SYSTEM
  FROM PROFITCENTER_V1."profitcenter"."profitcenter" p
  LEFT JOIN PROFITCENTER_V1."profitcenter"."profitcentertext" t
    ON t."ControllingArea" = p."ControllingArea" AND t."ProfitCenter" = p."ProfitCenter"
   AND t."ValidityEndDate" = p."ValidityEndDate" AND t."Language" = 'EN'
  WHERE p."ControllingArea" = 'A000' AND p."ProfitCenter" IN (SELECT "ProfitCenter" FROM COSTCENTER_V1."costcenter"."costcenter" WHERE "CompanyCode" = 'USC1');

CREATE OR REPLACE VIEW ACOCO_L1.ORGANISATION.ACTIVITY_TYPE
  COMMENT = 'L1 ORGANISATION.ACTIVITY_TYPE: one row per business object; sources BDC_CLD, SIMULATED. Generated from tools/l1_map.yml - do not edit.'
AS
  SELECT
    CAST(a."ControllingArea" AS VARCHAR) AS CONTROLLING_AREA,
    CAST(UPPER(TRIM(a."CostCtrActivityType")) AS VARCHAR) AS ACTIVITY_TYPE,
    CAST(TRIM(t."CostCtrActivityTypeName") AS VARCHAR) AS ACTIVITY_TYPE_NAME,
    CAST(a."CostCtrActivityTypeQtyUnit" AS VARCHAR) AS UNIT,
    CAST(a."AllocationCostElement" AS VARCHAR) AS COST_ELEMENT,
    CAST(NULL AS NUMBER(18,2)) AS PLANNED_PRICE,
    CAST(NULL AS VARCHAR) AS SENDER_COST_CENTER_ID,
    CAST(DECODE(a."CostCtrActivityType", 'ML-100', 'Analyst', 'ML-101', 'Consultant', 'ML-103', 'Manager', 'ML-104', 'Senior Manager', 'ML-105', 'Principal') AS VARCHAR) AS LEVEL,
    CAST(FALSE AS BOOLEAN) AS IS_AI_AGENT,
    'BDC_CLD' AS SOURCE_SYSTEM
  FROM COSTCENTERACTIVITYTYPE_V1."costcenteractivitytype"."costcenteractivitytype" a
  LEFT JOIN COSTCENTERACTIVITYTYPE_V1."costcenteractivitytype"."costcenteractivitytypetext" t
    ON t."ControllingArea" = a."ControllingArea" AND t."CostCtrActivityType" = a."CostCtrActivityType"
   AND t."ValidityEndDate" = a."ValidityEndDate" AND t."Language" = 'EN'
  WHERE a."ControllingArea" = 'A000' AND a."ValidityEndDate" = '9999-12-31'
  UNION ALL
  SELECT
    CAST(x."ControllingArea" AS VARCHAR) AS CONTROLLING_AREA,
    CAST(UPPER(TRIM(x."CostCtrActivityType")) AS VARCHAR) AS ACTIVITY_TYPE,
    CAST(x."CostCtrActivityTypeName" AS VARCHAR) AS ACTIVITY_TYPE_NAME,
    CAST(x."CostCtrActivityTypeQtyUnit" AS VARCHAR) AS UNIT,
    CAST(x."AllocationCostElement" AS VARCHAR) AS COST_ELEMENT,
    CAST(x."PlannedPrice" AS NUMBER(18,2)) AS PLANNED_PRICE,
    CAST(x."SenderCostCenter" AS VARCHAR) AS SENDER_COST_CENTER_ID,
    CAST(NULL AS VARCHAR) AS LEVEL,
    CAST(TRUE AS BOOLEAN) AS IS_AI_AGENT,
    'SIMULATED' AS SOURCE_SYSTEM
  FROM ACOCO_SIM.FINANCE_ACOCO.ACTIVITYTYPE_EXT x;

CREATE OR REPLACE VIEW ACOCO_L1.ORGANISATION.GL_ACCOUNT
  COMMENT = 'L1 ORGANISATION.GL_ACCOUNT: one row per business object; sources BDC_CLD. Generated from tools/l1_map.yml - do not edit.'
AS
  SELECT
    CAST(g."ChartOfAccounts" AS VARCHAR) AS CHART_OF_ACCOUNTS,
    CAST(g."GLAccount" AS VARCHAR) AS GL_ACCOUNT,
    CAST(t."GLAccountName" AS VARCHAR) AS GL_ACCOUNT_NAME,
    CAST(g."GLAccountType" AS VARCHAR) AS GL_ACCOUNT_TYPE,
    CAST(g."GLAccountGroup" AS VARCHAR) AS GL_ACCOUNT_GROUP,
    CAST(g."IsProfitLossAccount"::VARCHAR IN ('true', 'X', '1') AS BOOLEAN) AS IS_PROFIT_LOSS,
    CAST(DECODE(g."GLAccount", '0041000000', 'REVENUE', '0012100000', 'RECEIVABLE', '0094233007', 'OVERHEAD', '0094308000', 'PEOPLE_PLAN_AGENT_COST', 'Z610500', 'PEOPLE_COST', 'Z610501', 'PEOPLE_COST', 'Z610503', 'PEOPLE_COST', 'Z610504', 'PEOPLE_COST', 'Z610505', 'PEOPLE_COST') AS VARCHAR) AS ACOCO_ROLE,
    'BDC_CLD' AS SOURCE_SYSTEM
  FROM GENERALLEDGERACCOUNT_V1."generalledgeraccount"."generalledgeraccount" g
  LEFT JOIN GENERALLEDGERACCOUNT_V1."generalledgeraccount"."generalledgeraccounttext" t
    ON t."ChartOfAccounts" = g."ChartOfAccounts" AND t."GLAccount" = g."GLAccount" AND t."Language" = 'EN'
  WHERE g."ChartOfAccounts" = 'YCOA';

CREATE OR REPLACE VIEW ACOCO_L1.ORGANISATION.FISCAL_PERIOD
  COMMENT = 'L1 ORGANISATION.FISCAL_PERIOD: one row per business object; sources BDC_CLD. Generated from tools/l1_map.yml - do not edit.'
AS
  SELECT
    CAST(f."FiscalYearVariant" AS VARCHAR) AS FISCAL_YEAR_VARIANT,
    CAST(TRY_TO_NUMBER(f."FiscalYear"::VARCHAR) AS NUMBER) AS FISCAL_YEAR,
    CAST(TRY_TO_NUMBER(f."FiscalPeriod"::VARCHAR) AS NUMBER) AS FISCAL_PERIOD,
    CAST(TRY_TO_DATE(f."FiscalPeriodStartDate"::VARCHAR) AS DATE) AS PERIOD_START,
    CAST(TRY_TO_DATE(f."FiscalPeriodEndDate"::VARCHAR) AS DATE) AS PERIOD_END,
    CAST(TRY_TO_DATE(f."FiscalYearStartDate"::VARCHAR) AS DATE) AS FISCAL_YEAR_START,
    CAST(TRY_TO_DATE(f."FiscalYearEndDate"::VARCHAR) AS DATE) AS FISCAL_YEAR_END,
    'BDC_CLD' AS SOURCE_SYSTEM
  FROM FISCALYEAR_V1."fiscalyear"."fiscalperiod" f
  WHERE f."FiscalYearVariant" = 'V9' AND TRY_TO_NUMBER(f."FiscalYear"::VARCHAR) >= 2021 AND TRY_TO_NUMBER(f."FiscalPeriod"::VARCHAR) <= 12;

CREATE OR REPLACE VIEW ACOCO_L1.ORGANISATION.MD_GROUP
  COMMENT = 'L1 ORGANISATION.MD_GROUP: one row per business object; sources ACOCO_CONFIG. Generated from tools/l1_map.yml - do not edit.'
AS
  SELECT
